const nav=()=>"<header><a class=\"brand\" href=\""+q("index.html")+"\"><b>JOYA</b><i>CELL</i></a><nav>"+[["index.html",6],["categories.html",10],["product-details.html",11],["faq.html",12],["spreadsheet.html",7],["how-to-buy.html",8],["news.html",9]].map(x=>"<a href=\""+q(x[0])+"\">"+t[x[1]]+"</a>").join("")+"</nav><div class=\"langs\"></div></header>";
