const seoCopy={en:{label:"SEO Articles",card:"Research-led guides for product checks, QC and parcel questions.",title:"SEO articles: a research-first checklist",lead:"Practical reading for shoppers who want to narrow a shortlist before they enter the official order flow."},de:{label:"SEO-Artikel",card:"Rechercheleitfäden für Produktprüfung, QC und Paketfragen.",title:"SEO-Artikel: Checkliste für Recherche zuerst",lead:"Praktische Hinweise zum Eingrenzen einer Auswahl vor dem offiziellen Bestellablauf."},fr:{label:"Articles SEO",card:"Guides de recherche pour produit, QC et questions de colis.",title:"Articles SEO : une liste de vérification orientée recherche",lead:"Des conseils pratiques pour réduire une sélection avant le parcours officiel de commande."},es:{label:"Artículos SEO",card:"Guías de investigación para productos, QC y preguntas de paquetes.",title:"Artículos SEO: lista de verificación con investigación primero",lead:"Lecturas prácticas para reducir una selección antes del flujo oficial de pedido."},it:{label:"Articoli SEO",card:"Guide di ricerca per prodotti, QC e domande sul pacco.",title:"Articoli SEO: una checklist che parte dalla ricerca",lead:"Indicazioni pratiche per ridurre una lista prima del flusso ufficiale d’ordine."},pt:{label:"Artigos SEO",card:"Guias de pesquisa para produto, QC e dúvidas sobre encomendas.",title:"Artigos SEO: uma checklist com pesquisa primeiro",lead:"Leitura prática para reduzir uma seleção antes do fluxo oficial de pedido."},nl:{label:"SEO-artikelen",card:"Onderzoeksgidsen voor productchecks, QC en pakketvragen.",title:"SEO-artikelen: een checklist met onderzoek voorop",lead:"Praktische uitleg om een shortlist te maken vóór de officiële bestelstroom."},pl:{label:"Artykuły SEO",card:"Przewodniki po badaniu produktów, QC i pytań o paczkę.",title:"Artykuły SEO: lista kontrolna oparta na badaniu",lead:"Praktyczne wskazówki do zawężenia wyboru przed oficjalnym procesem zamówienia."}};
const seo=seoCopy[L[lang]?lang:"en"];
if(page==="seo")body="<main class=\"page seo-page\"><p class=\"eyebrow\">JOYACELL / "+seo.label+"</p><h1>"+seo.title+"</h1><p class=\"lead\">"+seo.lead+"</p><article id=\"shortlist\"><p class=\"eyebrow\">RESEARCH NOTE</p><h2>Build a shortlist before you make a decision</h2><p>A spreadsheet or category page is most useful when it helps you compare a small number of relevant records. Start with the product type, intended material or design detail; then keep the listing link and the exact variant together. A visual card can help you recognise an item, but it does not replace the live listing.</p><p>Use the same short checklist for each candidate: read the description, record the selected size or colour, compare the available images and note any question that still needs a live answer. This separates early discovery from the later order decision.</p></article><article id=\"qc\"><h2>Keep QC as a later confirmation</h2><p>Warehouse QC belongs after the product and chosen variant have been identified. Treat it as a separate confirmation step: compare what is shown with the listing details you already recorded. Joyacell does not operate the account, payment, warehouse or QC process; those actions are handled in the official platform flow.</p></article><article id=\"parcel\"><h2>Review parcel questions after packing</h2><p>Shipping is not determined by a product image or a spreadsheet row alone. Packed weight, dimensions, route rules and carrier measurement can affect the final parcel. Check the current official information before any transaction, and avoid treating an estimate as a fixed price or delivery time.</p></article><section class=\"seo-checklist\"><h2>A quick research checklist</h2><ul><li>Search by product type, material or style rather than a broad label.</li><li>Keep the live listing and selected variant together.</li><li>Compare listing details with images before using QC as confirmation.</li><li>Review packed-parcel information separately from product discovery.</li></ul><a class=\"button\" href=\""+find("joyagoo research checklist")+"\">"+t[5]+"</a></section></main>";
const seoHome="<section class=\"seo-home\"><p class=\"eyebrow\">06 — "+seo.label+"</p><div class=\"seo-home-head\"><div><h2>"+seo.title+"</h2><p class=\"copy\">"+seo.lead+"</p></div><a class=\"button\" href=\""+q("seo-articles.html")+"\">Read articles</a></div><div class=\"seo-grid\"><a href=\""+q("seo-articles.html")+"#shortlist\"><b>01</b><span>Shortlist with live listing details</span></a><a href=\""+q("seo-articles.html")+"#qc\"><b>02</b><span>Use QC as a later confirmation</span></a><a href=\""+q("seo-articles.html")+"#parcel\"><b>03</b><span>Review parcel questions separately</span></a></div></section>";
if(page==="home")body=body.replace("</main>",roleBlock+carousel+seoHome+"</main>");
const guideCopy={"en":{"title":"Joyagoo spreadsheet guides: products, QC, returns and shipping","intro":"Independent buying research: check the live listing and current Joyagoo terms before paying or shipping.","sections":[["Find and verify a product","Search by product type, then compare the live listing, seller, images, size chart and selected colour. Save the item link and the exact variant; a catalogue card alone cannot confirm stock or quality."],["Review warehouse QC photos","When warehouse photos are available, compare the item against the saved listing and variant. Check measurements and visible defects; request clarification through the order if a detail is missing. Photos cannot prove authenticity or test every feature."],["Decide whether to return or exchange","If a warehouse item differs from your order, record the issue and contact support through the order promptly. Check the seller’s eligibility, deadline, fees and available options in the live order before deciding; acceptance is not guaranteed."],["Estimate shipping and track a parcel","Separate item costs from domestic delivery, service fees, international shipping and possible taxes. Compare available routes using packed weight, dimensions, restrictions and insurance terms. Tracking updates and delivery times vary by carrier and destination."]]},"de":{"title":"Joyagoo Spreadsheet: Produkte, QC, Rückgabe und Versand","intro":"Unabhängige Kaufrecherche: Prüfen Sie Angebot und aktuelle Joyagoo-Bedingungen vor Zahlung oder Versand.","sections":[["Produkt finden und prüfen","Suchen Sie nach Produkttyp und vergleichen Sie Angebot, Verkäufer, Bilder, Größentabelle und gewählte Farbe. Speichern Sie Link und Variante; eine Katalogkarte bestätigt weder Bestand noch Qualität."],["QC-Fotos im Lager prüfen","Vergleichen Sie verfügbare Lagerfotos mit Angebot und Variante. Prüfen Sie Maße und sichtbare Mängel und fragen Sie im Auftrag nach fehlenden Details. Fotos beweisen weder Echtheit noch jede Funktion."],["Rückgabe oder Umtausch entscheiden","Dokumentieren Sie Abweichungen und kontaktieren Sie zeitnah den Support über die Bestellung. Prüfen Sie Rückgaberecht, Frist, Gebühren und Optionen im aktuellen Auftrag; eine Annahme ist nicht garantiert."],["Versand schätzen und verfolgen","Trennen Sie Produktpreis, Inlandsversand, Servicegebühren, internationalen Versand und mögliche Steuern. Vergleichen Sie Routen anhand von Paketgewicht, Maßen, Beschränkungen und Versicherung. Laufzeit und Tracking variieren."]]},"fr":{"title":"Guide Joyagoo spreadsheet : produits, QC, retours et livraison","intro":"Recherche indépendante : vérifiez l’annonce et les conditions Joyagoo actuelles avant de payer ou expédier.","sections":[["Trouver et vérifier un produit","Cherchez par type de produit puis comparez annonce, vendeur, images, guide des tailles et couleur choisie. Conservez le lien et la variante exacte ; une fiche ne garantit ni stock ni qualité."],["Examiner les photos QC en entrepôt","Comparez les photos disponibles à l’annonce et à la variante choisie. Vérifiez mesures et défauts visibles ; demandez une précision via la commande si nécessaire. Les photos ne prouvent ni authenticité ni fonctionnement complet."],["Décider d’un retour ou échange","Documentez tout écart et contactez rapidement le support depuis la commande. Vérifiez l’éligibilité du vendeur, les délais, frais et options affichés ; le retour n’est pas garanti."],["Estimer et suivre la livraison","Distinguez prix, livraison intérieure, frais de service, livraison internationale et taxes éventuelles. Comparez les routes selon poids emballé, dimensions, restrictions et assurance. Suivi et délais varient."]]},"es":{"title":"Guías Joyagoo spreadsheet: productos, QC, devoluciones y envío","intro":"Investigación independiente: comprueba el anuncio y las condiciones actuales de Joyagoo antes de pagar o enviar.","sections":[["Busca y verifica el producto","Busca por tipo y compara anuncio, vendedor, imágenes, tabla de tallas y color elegido. Guarda enlace y variante exacta; una tarjeta no garantiza existencias ni calidad."],["Revisa las fotos QC del almacén","Compara las fotos disponibles con el anuncio y la variante. Comprueba medidas y defectos visibles; solicita detalles desde el pedido si falta información. Las fotos no prueban autenticidad ni todas las funciones."],["Decide una devolución o cambio","Documenta cualquier diferencia y contacta pronto con soporte desde el pedido. Revisa elegibilidad del vendedor, plazo, costes y opciones actuales; la aceptación no está garantizada."],["Calcula y sigue el envío","Separa precio del producto, envío nacional, tarifas de servicio, envío internacional y posibles impuestos. Compara rutas por peso embalado, dimensiones, restricciones y seguro. Seguimiento y plazos varían."]]},"it":{"title":"Guide Joyagoo spreadsheet: prodotti, QC, resi e spedizione","intro":"Ricerca indipendente: controlla inserzione e condizioni Joyagoo aggiornate prima di pagare o spedire.","sections":[["Trova e verifica il prodotto","Cerca per tipo e confronta inserzione, venditore, immagini, tabella taglie e colore scelto. Conserva link e variante esatta; una scheda non garantisce disponibilità o qualità."],["Controlla le foto QC in magazzino","Confronta le foto disponibili con inserzione e variante. Verifica misure e difetti visibili; chiedi dettagli tramite ordine se necessario. Le foto non provano autenticità o tutte le funzioni."],["Decidi reso o cambio","Documenta le differenze e contatta presto l’assistenza dall’ordine. Verifica idoneità del venditore, scadenze, costi e opzioni attuali; l’accettazione non è garantita."],["Stima e traccia la spedizione","Separa prezzo del prodotto, spedizione interna, commissioni, spedizione internazionale e possibili imposte. Confronta rotte per peso imballato, dimensioni, restrizioni e assicurazione. Tempi e tracciamento variano."]]},"pt":{"title":"Guias Joyagoo spreadsheet: produtos, QC, devoluções e envio","intro":"Pesquisa independente: confirme o anúncio e as condições atuais da Joyagoo antes de pagar ou enviar.","sections":[["Encontrar e verificar um produto","Pesquise pelo tipo e compare anúncio, vendedor, imagens, tabela de tamanhos e cor escolhida. Guarde ligação e variante exata; um cartão não garante stock ou qualidade."],["Rever fotos QC no armazém","Compare as fotos disponíveis com o anúncio e a variante. Verifique medidas e defeitos visíveis; peça detalhes através da encomenda se necessário. Fotos não provam autenticidade nem todas as funções."],["Decidir devolução ou troca","Registe diferenças e contacte rapidamente o apoio pela encomenda. Confirme elegibilidade do vendedor, prazo, custos e opções atuais; a aceitação não é garantida."],["Estimar e acompanhar o envio","Separe preço do artigo, envio interno, taxas de serviço, envio internacional e impostos possíveis. Compare rotas pelo peso embalado, dimensões, restrições e seguro. Rastreio e prazos variam."]]},"nl":{"title":"Joyagoo spreadsheet gidsen: producten, QC, retouren en verzending","intro":"Onafhankelijk aankooponderzoek: controleer de actuele aanbieding en Joyagoo-voorwaarden vóór betaling of verzending.","sections":[["Product zoeken en controleren","Zoek op producttype en vergelijk aanbieding, verkoper, beelden, maattabel en gekozen kleur. Bewaar link en exacte variant; een kaart garandeert geen voorraad of kwaliteit."],["QC-foto’s in het magazijn beoordelen","Vergelijk beschikbare foto’s met aanbieding en variant. Controleer maten en zichtbare gebreken; vraag via de bestelling om ontbrekende details. Foto’s bewijzen geen echtheid of volledige werking."],["Retour of omruiling beslissen","Leg afwijkingen vast en neem snel contact op via de bestelling. Controleer voorwaarden van de verkoper, termijn, kosten en beschikbare opties; acceptatie is niet gegarandeerd."],["Verzending schatten en volgen","Scheid productprijs, binnenlandse bezorging, servicekosten, internationale verzending en mogelijke belastingen. Vergelijk routes op verpakt gewicht, afmetingen, beperkingen en verzekering. Tracking en levertijd verschillen."]]},"pl":{"title":"Poradniki Joyagoo spreadsheet: produkty, QC, zwroty i wysyłka","intro":"Niezależna analiza zakupów: sprawdź aktualną ofertę i warunki Joyagoo przed płatnością lub wysyłką.","sections":[["Znajdź i sprawdź produkt","Szukaj według typu i porównaj ofertę, sprzedawcę, zdjęcia, tabelę rozmiarów i wybrany kolor. Zachowaj link i dokładny wariant; karta nie gwarantuje dostępności ani jakości."],["Sprawdź zdjęcia QC w magazynie","Porównaj dostępne zdjęcia z ofertą i wariantem. Sprawdź wymiary i widoczne wady; brakujące szczegóły wyjaśnij przez zamówienie. Zdjęcia nie potwierdzają autentyczności ani wszystkich funkcji."],["Zdecyduj o zwrocie lub wymianie","Udokumentuj niezgodność i szybko skontaktuj się z obsługą przez zamówienie. Sprawdź warunki sprzedawcy, termin, koszty i dostępne opcje; przyjęcie zwrotu nie jest gwarantowane."],["Oszacuj i śledź wysyłkę","Oddziel cenę produktu, dostawę krajową, opłaty usługowe, wysyłkę międzynarodową i możliwe podatki. Porównaj trasy według wagi paczki, wymiarów, ograniczeń i ubezpieczenia. Terminy i śledzenie są zmienne."]]}};
const guide=(code,home=false)=>{const d=guideCopy[code]||guideCopy.en;const sections=d.sections.map((x,i)=>`<article id="${['shortlist','qc','returns','parcel'][i]}"><h2>${x[0]}</h2><p>${x[1]}</p></article>`).join("");return home?`<section class="home-full-seo"><p class="eyebrow">07 — ${seo.label}</p><h2>${d.title}</h2><p class="lead">${d.intro}</p>${sections}</section>`:`<main class="page seo-page"><p class="eyebrow">JOYACELL / ${seo.label}</p><h1>${d.title}</h1><p class="lead">${d.intro}</p>${sections}</main>`};
if(page==="home")body=body.replace("</main>",guide(lang,true)+"</main>");
if(page==="seo")body=guide(lang);
if(page==="faq"){const d=guideCopy[lang]||guideCopy.en;body=`<main class="page"><p class="eyebrow">JOYACELL / FAQ</p><h1>${t[21]}</h1><p class="lead">${d.intro}</p><div class="faq">${(joyFaqQuestions[lang]||joyFaqQuestions.en).map((question,i)=>`<details><summary>${question}</summary><p>${d.sections[[0,0,1,3,3,3,2,3][i]][1]}</p></details>`).join("")}</div></main>`;}
const pageCopy={
en:{cat:"Use the category page to make a short list, not a shipping promise. Check the live record before choosing an item.",st:["Spreadsheet: find a shorter path through a broad catalogue","A spreadsheet helps reduce browsing friction without replacing careful review. Use search terms, category paths and source information to make a smaller shortlist.","Use it for discovery","Search by product type, material or style; use categories when the first search is too broad; keep details with the link you plan to review.","Not a promise","Listings can change. A spreadsheet cannot guarantee availability, price, quality, route eligibility or delivery time."],news:["Check a parcel from the listing outward","Start with stable details: listing description, selected size or colour, seller images and product link. This makes it easier to recognise the right item later.","Warehouse QC is a later check, not a substitute for reading the listing. Compare a received item with the selected variant and decide what matters to you.","Shipping cost can depend on the packed parcel, not product price alone. Weight, dimensions, route rules and carrier measurement can change the final basis. Never treat an estimate as a fixed cost or delivery time."]},
de:{cat:"Nutzen Sie die Kategorieseite für eine kurze Auswahl, nicht als Versandversprechen. Prüfen Sie den aktuellen Eintrag, bevor Sie einen Artikel wählen.",st:["Spreadsheet: ein kürzerer Weg durch einen großen Katalog","Ein Spreadsheet verringert den Suchaufwand, ersetzt aber keine sorgfältige Prüfung. Nutzen Sie Suchbegriffe, Kategoriepfade und Quellenangaben für eine kleinere Auswahl.","Für die Entdeckung nutzen","Suchen Sie nach Produkttyp, Material oder Stil; verwenden Sie Kategorien bei zu breiter Suche und bewahren Sie Details mit dem zu prüfenden Link auf.","Keine Zusage","Angebote können sich ändern. Ein Spreadsheet garantiert weder Verfügbarkeit, Preis, Qualität, Routenberechtigung noch Lieferzeit."],news:["Ein Paket vom Angebot aus prüfen","Beginnen Sie mit stabilen Angaben: Beschreibung, gewählte Größe oder Farbe, Verkäuferbilder und Produktlink. So erkennen Sie den richtigen Artikel später leichter.","Lager-QC ist eine spätere Prüfung und kein Ersatz für das Lesen des Angebots. Vergleichen Sie den erhaltenen Artikel mit der gewählten Variante und entscheiden Sie, was Ihnen wichtig ist.","Versandkosten können vom gepackten Paket abhängen, nicht nur vom Produktpreis. Gewicht, Maße, Routenregeln und Carrier-Messung können die Grundlage verändern. Eine Schätzung ist kein Festpreis oder Liefertermin."]},
fr:{cat:"Utilisez la page catégorie pour établir une courte liste, non comme promesse d’expédition. Vérifiez la fiche en direct avant de choisir un article.",st:["Spreadsheet : un chemin plus court dans un vaste catalogue","Un spreadsheet réduit le temps de navigation sans remplacer une vérification attentive. Utilisez les termes de recherche, parcours de catégories et sources pour créer une sélection réduite.","Pour découvrir","Cherchez par type de produit, matière ou style ; utilisez les catégories lorsque la première recherche est trop large et gardez les détails avec le lien à vérifier.","Aucune promesse","Les annonces peuvent changer. Un spreadsheet ne garantit ni disponibilité, ni prix, ni qualité, ni éligibilité d’itinéraire, ni délai."],news:["Vérifier un colis à partir de l’annonce","Commencez par les éléments stables : description, taille ou couleur choisie, images du vendeur et lien produit. Cela aide à reconnaître le bon article plus tard.","Le QC d’entrepôt est un contrôle ultérieur, pas un substitut à la lecture de l’annonce. Comparez l’article reçu à la variante choisie et décidez de ce qui compte pour vous.","Le coût d’expédition peut dépendre du colis emballé et non du seul prix produit. Poids, dimensions, règles de route et mesure du transporteur peuvent modifier le total. Une estimation n’est ni prix fixe ni délai." ]},
es:{cat:"Usa la página de categoría para crear una lista corta, no como promesa de envío. Revisa la ficha en directo antes de elegir un artículo.",st:["Spreadsheet: una ruta más corta por un catálogo amplio","Una hoja de cálculo reduce la fricción al explorar sin sustituir una revisión cuidadosa. Usa términos, rutas de categoría e información de origen para crear una selección más pequeña.","Úsalo para descubrir","Busca por tipo de producto, material o estilo; usa categorías cuando la primera búsqueda sea demasiado amplia y conserva los detalles junto al enlace que revisarás.","No es una promesa","Los anuncios pueden cambiar. Una hoja de cálculo no garantiza disponibilidad, precio, calidad, elegibilidad de ruta ni tiempo de entrega."],news:["Revisa un paquete desde el anuncio hacia afuera","Empieza con datos estables: descripción, talla o color elegido, imágenes del vendedor y enlace del producto. Así será más fácil reconocer el artículo correcto después.","El QC de almacén es una comprobación posterior, no sustituye leer el anuncio. Compara el artículo recibido con la variante elegida y decide qué te importa.","El coste de envío puede depender del paquete embalado, no solo del precio del producto. Peso, dimensiones, reglas de ruta y medición del transportista pueden cambiar el total. Una estimación no es coste ni plazo fijo."]},
it:{cat:"Usa la pagina categoria per creare una lista breve, non come promessa di spedizione. Controlla la scheda dal vivo prima di scegliere un articolo.",st:["Spreadsheet: un percorso più breve in un catalogo ampio","Un foglio di calcolo riduce la navigazione senza sostituire una verifica accurata. Usa termini di ricerca, percorsi di categoria e fonti per una selezione più piccola.","Usalo per scoprire","Cerca per tipo di prodotto, materiale o stile; usa le categorie se la prima ricerca è troppo ampia e conserva i dettagli con il link da verificare.","Non è una promessa","Le inserzioni possono cambiare. Un foglio di calcolo non garantisce disponibilità, prezzo, qualità, idoneità della rotta o tempi di consegna."],news:["Controlla un pacco partendo dall’inserzione","Inizia dai dettagli stabili: descrizione, taglia o colore scelto, immagini del venditore e link prodotto. Così è più facile riconoscere l’articolo giusto in seguito.","Il QC di magazzino è un controllo successivo, non sostituisce la lettura dell’inserzione. Confronta l’articolo ricevuto con la variante scelta e decidi cosa conta per te.","Il costo di spedizione può dipendere dal pacco imballato, non solo dal prezzo del prodotto. Peso, dimensioni, regole di rotta e misurazione del vettore possono cambiare il totale. Una stima non è un costo o un termine fisso."]},
pt:{cat:"Use a página da categoria para criar uma lista curta, não como promessa de envio. Verifique o registo em direto antes de escolher um artigo.",st:["Spreadsheet: um caminho mais curto num catálogo amplo","Uma folha de cálculo reduz o esforço de navegação sem substituir uma revisão cuidadosa. Use termos de pesquisa, percursos de categoria e fontes para fazer uma seleção menor.","Use para descobrir","Pesquise por tipo de produto, material ou estilo; use categorias quando a primeira pesquisa for ampla demais e guarde os detalhes com a ligação a rever.","Não é uma promessa","Os anúncios podem mudar. Uma folha de cálculo não garante disponibilidade, preço, qualidade, elegibilidade da rota ou prazo de entrega."],news:["Verifique uma encomenda a partir do anúncio","Comece por detalhes estáveis: descrição, tamanho ou cor escolhida, imagens do vendedor e ligação do produto. Assim é mais fácil reconhecer o artigo certo depois.","O QC de armazém é uma verificação posterior, não substitui ler o anúncio. Compare o artigo recebido com a variante escolhida e decida o que importa para si.","O custo de envio pode depender da encomenda embalada, não apenas do preço do produto. Peso, dimensões, regras de rota e medição da transportadora podem alterar o total. Uma estimativa não é custo ou prazo fixo."]},
nl:{cat:"Gebruik de categoriepagina om een korte lijst te maken, niet als verzendbelofte. Controleer de actuele vermelding voordat u een artikel kiest.",st:["Spreadsheet: een kortere weg door een brede catalogus","Een spreadsheet vermindert zoekwerk zonder zorgvuldige controle te vervangen. Gebruik zoektermen, categorieroutes en broninformatie voor een kleinere selectie.","Gebruik voor ontdekking","Zoek op producttype, materiaal of stijl; gebruik categorieën wanneer de eerste zoekopdracht te breed is en bewaar details bij de link die u wilt controleren.","Geen belofte","Aanbiedingen kunnen veranderen. Een spreadsheet garandeert geen beschikbaarheid, prijs, kwaliteit, routegeschiktheid of levertijd."],news:["Controleer een pakket vanuit de aanbieding","Begin met stabiele details: beschrijving, gekozen maat of kleur, verkopersfoto’s en productlink. Daardoor herkent u het juiste artikel later eenvoudiger.","Magazijn-QC is een latere controle, geen vervanging voor het lezen van de aanbieding. Vergelijk het ontvangen artikel met de gekozen variant en bepaal wat voor u telt.","Verzendkosten kunnen afhangen van het ingepakte pakket, niet alleen van de productprijs. Gewicht, afmetingen, routeregels en meting door de vervoerder kunnen het totaal veranderen. Een schatting is geen vaste prijs of levertijd."]},
pl:{cat:"Użyj strony kategorii do utworzenia krótkiej listy, a nie jako obietnicy wysyłki. Sprawdź aktualną ofertę przed wyborem produktu.",st:["Spreadsheet: krótsza droga przez szeroki katalog","Arkusz ogranicza czas przeglądania, ale nie zastępuje starannej kontroli. Użyj fraz, ścieżek kategorii i informacji źródłowych, aby stworzyć mniejszą listę.","Używaj do odkrywania","Szukaj według typu produktu, materiału lub stylu; użyj kategorii, gdy pierwsze wyszukiwanie jest zbyt szerokie, i zachowaj szczegóły przy linku do sprawdzenia.","To nie obietnica","Oferty mogą się zmieniać. Arkusz nie gwarantuje dostępności, ceny, jakości, kwalifikacji trasy ani terminu dostawy."],news:["Sprawdź paczkę, zaczynając od oferty","Zacznij od stabilnych danych: opisu, wybranego rozmiaru lub koloru, zdjęć sprzedawcy i linku produktu. Dzięki temu łatwiej później rozpoznać właściwy artykuł.","QC magazynowe to późniejsza kontrola, a nie zastępstwo czytania oferty. Porównaj otrzymany artykuł z wybranym wariantem i zdecyduj, co jest ważne.","Koszt wysyłki może zależeć od zapakowanej paczki, nie tylko ceny produktu. Waga, wymiary, zasady trasy i pomiar przewoźnika mogą zmienić sumę. Szacunek nie jest stałą ceną ani terminem dostawy."]}
};
const localPage=pageCopy[lang]||pageCopy.en;
if(page==="categories"){body=`<main class="page"><p class="eyebrow">JOYACELL / ${t[10]}</p><h1>${t[13]}</h1><p class="lead">${t[14]}</p>${cards()}</main>`;}
if(page==="spreadsheet")body=`<main class="page"><p class="eyebrow">JOYACELL / ${t[7]}</p><h1>${localPage.st[0]}</h1><p class="lead">${localPage.st[1]}</p>${search()}<section class="split"><div><h2>${localPage.st[2]}</h2><p>${localPage.st[3]}</p></div><div><h2>${localPage.st[4]}</h2><p>${localPage.st[5]}</p></div></section><a class="button" href="${q("categories.html")}">${t[10]}</a></main>`;
if(page==="news")body=`<main class="page"><p class="eyebrow">JOYACELL / ${t[9]}</p><h1>${t[17]}</h1><p class="lead">${t[18]}</p><article><p class="eyebrow">RESEARCH NOTE · SEPTEMBER 2026</p><h2>${localPage.news[0]}</h2><p>${localPage.news[1]}</p><p>${localPage.news[2]}</p><p>${localPage.news[3]}</p></article></main>`;
document.documentElement.lang=L[lang]?lang:"en";document.title=(page==="seo"?(guideCopy[lang]||guideCopy.en).title:document.title.split(" | Joyacell")[0])+" | Joyacell";document.getElementById("app").innerHTML=nav()+body+footer();
const headerBrand=document.querySelector("header .brand");if(headerBrand){headerBrand.setAttribute("aria-label","Joyacell home");headerBrand.innerHTML="<img src=\"assets/joyagoo-logo-user.svg\" alt=\"Joyagoo\" style=\"filter:none\">";}
if(page==="home"){const hero=document.querySelector(".hero");if(hero){hero.insertAdjacentHTML("beforeend",heroVisual);hero.classList.add("hero-image-layout","cyber-hero");if(!matchMedia("(prefers-reduced-motion: reduce)").matches&&!matchMedia("(max-width:850px)").matches){const visual=hero.querySelector(".hero-visual");hero.addEventListener("pointermove",event=>{const box=hero.getBoundingClientRect();const x=(event.clientX-box.left)/box.width-.5;const y=(event.clientY-box.top)/box.height-.5;visual.style.setProperty("--tilt-x",String(y*-2.4)+"deg");visual.style.setProperty("--tilt-y",String(x*2.4)+"deg");});hero.addEventListener("pointerleave",()=>{visual.style.setProperty("--tilt-x","0deg");visual.style.setProperty("--tilt-y","0deg");});let ticking=false;addEventListener("scroll",()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const offset=hero.getBoundingClientRect().top*.035;visual.style.setProperty("--hero-shift",offset+"px");ticking=false;});},{passive:true});}}}
const topNav=document.querySelector("header nav");if(topNav){const seoNav=document.createElement("a");seoNav.href=q("seo-articles.html");seoNav.textContent=seo.label;const spreadsheetLink=topNav.querySelectorAll("a")[4];topNav.insertBefore(seoNav,spreadsheetLink);}
if(page==="home"){const paths=document.querySelector(".paths");if(paths){const seoPath=document.createElement("a");seoPath.href=q("seo-articles.html");seoPath.innerHTML="<b>"+seo.label+"</b><span>"+seo.card+"</span>";paths.appendChild(seoPath);}}
const languagePanel=document.querySelector(".langs");if(languagePanel){languagePanel.innerHTML="<div class=\"language-menu\"><button class=\"language-toggle\" type=\"button\" aria-expanded=\"false\" aria-controls=\"language-options\">Language: "+(L[lang]?lang:"en").toUpperCase()+"</button><div id=\"language-options\" style=\"display:none\">"+Object.keys(L).map(x=>"<a class=\"langlink "+(x===lang?"on":"")+"\" href=\""+languageUrl(x)+"\" data-language=\""+x+"\">"+x.toUpperCase()+"</a>").join("")+"</div></div>";const toggle=languagePanel.querySelector(".language-toggle"),options=languagePanel.querySelector("#language-options");toggle.addEventListener("click",()=>{const opening=options.style.display==="none";options.style.display=opening?"grid":"none";toggle.setAttribute("aria-expanded",String(opening));});document.querySelectorAll(".langlink").forEach(a=>a.addEventListener("click",event=>{event.preventDefault();sessionStorage.setItem("joyacell_scroll",String(scrollY));location.assign(a.href);}));}
const saved=sessionStorage.getItem("joyacell_scroll");if(saved!==null){requestAnimationFrame(()=>scrollTo(0,Number(saved)));sessionStorage.removeItem("joyacell_scroll");}
const compactMobile=()=>{if(!matchMedia("(max-width:850px)").matches)return;document.head.insertAdjacentHTML("beforeend",`<style id="joyacell-mobile-compact">header,main,footer{padding-left:14px;padding-right:14px}header{min-height:0;padding-top:9px;padding-bottom:9px;gap:10px}nav{gap:11px}nav a{font-size:12px}.section,.page,.roles,.main-gallery,.seo-home{padding-top:26px!important;padding-bottom:26px!important}.hero{padding:24px 0!important;gap:16px}.hero-copy{min-height:0!important}h1{font-size:clamp(2rem,10vw,3.1rem)!important}.lead{font-size:16px;margin-bottom:16px}.micro{font-size:12px}.paths a{padding:14px 0}.cards a{min-height:94px;padding:11px}.roles,.main-gallery{padding-top:26px!important;padding-bottom:26px!important}.role-grid article{padding:16px}.main-gallery>div:first-child{gap:10px}.reel{margin-top:14px;padding:9px 0}.seo-grid{margin-top:15px}.seo-grid a{padding:14px}.seo-home-head{gap:12px}.seo-page>article{display:none}.mobile-article{display:block;margin:10px 0;padding:0;border:1px solid var(--line);background:#fff}.mobile-article summary{padding:14px;font-size:16px;line-height:1.3}.mobile-article p{padding:0 14px 14px;margin:0;color:var(--muted);font-size:14px}.mobile-article[open] summary{border-bottom:1px solid var(--line)}.faq{margin-top:20px}.faq details{padding:12px 0}.faq summary{font-size:16px}.faq details p{font-size:14px;margin:10px 0 0}.check{margin:22px 0}.check p{padding:12px 0}footer{min-height:0;padding-top:18px;padding-bottom:18px}</style>`);if(page==="seo"){document.querySelectorAll(".seo-page article").forEach((article,index)=>{const details=document.createElement("details");details.className="mobile-article";const heading=article.querySelector("h2");const summary=document.createElement("summary");summary.textContent=heading?heading.textContent:(index===0?"Research basis and decision order":"Research section");details.appendChild(summary);if(heading)heading.remove();while(article.firstChild)details.appendChild(article.firstChild);article.replaceWith(details);});}};
compactMobile();
if(matchMedia("(max-width:850px)").matches&&page==="home"){document.head.insertAdjacentHTML("beforeend",`<style>.home-full-seo .mobile-article{display:block;margin:10px 0;padding:0;border:1px solid var(--line);background:#11170f}.home-full-seo .mobile-article summary{padding:14px;font-size:16px;line-height:1.3;cursor:pointer}.home-full-seo .mobile-article p{padding:0 14px 14px;margin:0;color:var(--muted);font-size:14px}.home-full-seo .mobile-article[open] summary{border-bottom:1px solid var(--line)}</style>`);document.querySelectorAll(".home-full-seo article").forEach((article,index)=>{const details=document.createElement("details");details.className="mobile-article";const heading=article.querySelector("h2");const summary=document.createElement("summary");summary.textContent=heading?heading.textContent:("Research section "+(index+1));details.appendChild(summary);if(heading)heading.remove();while(article.firstChild)details.appendChild(article.firstChild);article.replaceWith(details);});}
